  for (let i = 0; i < 4; i++) { const y0 = 5.3 + i * .975, y1 = y0 + .975, w0 = tier(y0), w1 = tier(y1);
    s.push([-w0, y0, -w1, y1, .19, 1], [w0, y0, w1, y1, .19, 1], [-w1, y1, w1, y1, i === 3 ? .19 : .1, i === 3 ? 1 : 0], [-w0, y0, w1, y1, .08, 0], [w0, y0, -w1, y1, .08, 0], [0, y0, 0, y1, .07, 0]); }
