  const byW = new Map(); for (const st of sticks) { if (!pick(st)) continue; const w = Math.max(st[4] * wMul + wAdd, 1.05 / k); const key = Math.round(w * 400); if (!byW.has(key)) byW.set(key, []); byW.get(key).push(st); }
